import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();

        int mid = n * (n - 1) / 2;
        int max_idx = n * (n - 1);
        int[][] dp_array = new int[n + 1][max_idx + 1];
        int[][] dp1_array = new int[n + 1][max_idx + 1];

        dp_array[1][mid] = 1;

        for (int i = 2; i <= n; i++) {
            int low = mid - (i - 1) * (i - 2) / 2;
            int high = mid + (i - 1) * (i - 2) / 2;
            for (int x = low; x <= high; x++) {
                for (int delta = -i + 1; delta < i; delta++) {
                    int idx = x + delta;
                    if (0 <= idx && idx <= max_idx) {
                        dp_array[i][idx] = (int) ((dp_array[i][idx] + (long) dp_array[i - 1][x] * (i - Math.abs(delta))) % mod);
                    }
                }
            }
        }

        for (int i = 2; i <= n; i++) {
            int low = mid - (i - 1) * (i - 2) / 2;
            int high = mid + (i - 1) * (i - 2) / 2;
            for (int x = low; x <= high; x++) {
                dp1_array[i][x] = (int) ((long) dp1_array[i - 1][x] * i % mod);
            }
            for (int x = low; x <= high; x++) {
                for (int d = 1; d < i; d++) {
                    int idx = x - d;
                    if (0 <= idx && idx <= max_idx) {
                        dp1_array[i][idx] = (int) ((dp1_array[i][idx] + (long) dp_array[i - 1][x] * (i - d)) % mod);
                    }
                }
            }
        }

        long sum = 0;
        for (int x = mid + 1; x <= max_idx; x++) {
            sum += dp1_array[n][x];
        }
        System.out.println((int) (sum % mod));
        scanner.close();
    }
}
